    if (left.length && left.length < prev.length) out.push({ id: 'past:' + prevYm, kind: 'past', when: 'late', level: 'warn', ym: prevYm, lines: left.map(p => ({ id: p.id, name: p.name, amount: p.planned })), amount: sum(left.map(p => p.planned)) });
