function reminderScheduleAll(state, today, lead, days) {
  const out = reminderSchedule(state, today, BASE_CURRENCY, lead, days);
  for (const b of companyBooks(state)) for (const x of reminderSchedule(b.book, today, b.cur, lead, days)) out.push({ ...x, book: b.key, cur: b.cur });
  return out.sort((a, b) => a.sendDate < b.sendDate ? -1 : a.sendDate > b.sendDate ? 1 : 0);
}

// ---- js/core/goals.js
/* Dorax Finance — calculations: savings goals and funds. */
// ---------- savings goals ----------
// A goal has a target (and optionally a deadline); a fund is an open-ended envelope. Both carry a monthly plan per year and are filled by
// recorded movements (contributions > 0, withdrawals < 0). "Saved" is always the sum of movements, never a typed-in number.
